#include <bits/stdc++.h>
using namespace std;using ll=long long;
void req(bool p,string s){if(!p)throw runtime_error(s);}
vector<int> build(const vector<int>&s,int a,int m){int t=s.size(),n=2*t+m;vector<int>g(n);for(int u=0;u<n;u++)for(int v=u+1;v<n;v++){bool uv=false;if(v<t)uv=(s[u]>>v)&1;else if(u>=t&&v<2*t)uv=(s[v-t]>>(u-t))&1;else if(u<t&&v<2*t)uv=(u==a&&v-t==a);else if(u<t)uv=false;else if(u<2*t)uv=true;else uv=true;g[uv?u:v]|=1<<(uv?v:u);}return g;}
struct Result{ll H=0,fixed=0;set<vector<int>> normalized,orbits;};
Result words(const vector<int>&g,bool keep){int n=g.size(),t=n/2,full=(1<<n)-1;Result z;vector<int>p;function<void(int,int)>rec=[&](int last,int used){if(used==full){z.H++;vector<int>j;for(int i=n-1;i>=0;i--)j.push_back((p[i]+t)%n);if(keep)z.orbits.insert(min(p,j));if(j==p){z.fixed++;if(keep){vector<int>a(n);for(int u=0;u<n;u++)for(int v=0;v<n;v++)if(g[p[u]]>>p[v]&1)a[u]|=1<<v;for(int i=0;i<n-1;i++)req(a[i]>>(i+1)&1,"normalized path");for(int u=0;u<n;u++)for(int v=0;v<n;v++)req(((a[u]>>v)&1)==((a[n-1-v]>>(n-1-u))&1),"normalized reversal");z.normalized.insert(a);}}return;}for(int v=0;v<n;v++)if(!(used>>v&1)&&(g[last]>>v&1)){p.push_back(v);rec(v,used|1<<v);p.pop_back();}};for(int v=0;v<n;v++){p={v};rec(v,1<<v);}return z;}
vector<int> graph(int n,int code){vector<int>a(n);int p=0;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++,p++){bool uv=(code>>p)&1;a[uv?u:v]|=1<<(uv?v:u);}return a;}
void sidecheck(const vector<int>&s,int a){int n=s.size(),full=(1<<n)-1;vector<ll>h(1<<n),ends(1<<n);ll e=0;h[0]=1;function<void(int,int,int)>dfs=[&](int first,int last,int used){h[used]++;if(last==a)ends[used]++;if(used==full&&first==a)e++;for(int v=0;v<n;v++)if(!(used>>v&1)&&(s[last]>>v&1))dfs(first,v,used|1<<v);};for(int v=0;v<n;v++)dfs(v,v,1<<v);ll q=0;for(int mask=1;mask<=full;mask++)q+=ends[mask]*h[full^mask];auto z=words(build(s,a,0),false);req(z.fixed==h[full]+q-e,"full-word fixed fibre");req(z.H==h[full]*h[full]+q*q-e*e,"physical boundary source");}
ll automorphisms(const vector<int>&a,bool anti){int n=a.size();vector<int>p(n),deg(n);for(int i=0;i<n;i++)deg[i]=__builtin_popcount((unsigned)a[i]);vector<vector<int>> options(n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(deg[j]==(anti?n-1-deg[i]:deg[i]))options[i].push_back(j);ll out=0;function<void(int,int)>rec=[&](int i,int used){if(i==n){bool ok=true;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++)if(((a[u]>>v)&1)!=(((a[p[u]]>>p[v])&1)^int(anti)))ok=false;out+=ok;return;}for(int v:options[i])if(!(used>>v&1)){p[i]=v;rec(i+1,used|1<<v);}};rec(0,0);return out;}
int main(){ll sides=0;for(int n=1;n<=4;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++)for(int a=0;a<n;a++){sidecheck(graph(n,code),a);sides++;}mt19937 rng(1971221);for(int k=0;k<40;k++){sidecheck(graph(5,rng()&1023),k%5);sides++;}cout<<"PASS independent_full_word_sides "<<sides<<"\n";
for(int k=1;k<=6;k++){int t=k+2,n=2*t;auto s=graph(t,(1<<(t*(t-1)/2))-1);s[0]^=1<<(t-1);s[t-1]|=1;auto a=build(s,0,0);auto z=words(a,true);ll h=(1LL<<k)+1;req(z.H==2*h*h-1&&z.fixed==2*h-1,"family H and fixed words");req(z.orbits.size()==(size_t)(h*h+h-1),"literal converse orbits");req(z.normalized.size()==(size_t)z.fixed,"literal normalized class fibre");req(automorphisms(a,false)==1&&automorphisms(a,true)==1,"complete degree-class bijections");vector<int>d;for(int row:a)d.push_back(__builtin_popcount((unsigned)row));sort(d.begin(),d.end());vector<int>expect{1};for(int i=1;i<=n-2;i++)expect.push_back(i);expect.push_back(n-2);req(d==expect,"degree sequence");set<pair<int,int>>freeorbits;for(int u=0;u<n;u++)for(int v=u+2;v<n;v++)freeorbits.insert(min(make_pair(u,v),make_pair(n-1-v,n-1-u)));req((int)freeorbits.size()==t*(t-1),"normalized total exponent");if(k==5){vector<int>w{1,2,3,4,5,6,0,7,13,12,11,10,9,8};set<int>used(w.begin(),w.end());req(used.size()==14,"displayed path distinct");for(int i=0;i<13;i++)req(a[w[i]]>>w[i+1]&1,"displayed arcs");for(int i=0;i<14;i++)req(w[i]==(w[13-i]+7)%14,"displayed involution");}cout<<"FAMILY "<<k<<" H "<<z.H<<" fixed "<<z.fixed<<" orbits "<<z.orbits.size()<<" normalized "<<z.normalized.size()<<" exponent "<<freeorbits.size()<<"\n";}
}
